function modelFile = build_dclink_logic_model(outputFolder)
%BUILD_DCLINK_LOGIC_MODEL Create OEM-style DC-link supervisory logic model.
% Requires MATLAB, Simulink and the MATLAB Function block capability.
% The generated model contains no Simscape plant; connect its I/O to the
% plant generated by build_dclink_simscape_model.m or to an HIL interface.

if nargin < 1, outputFolder = pwd; end
assert(license('test','Simulink')==1,'Simulink license is required.');
if ~exist(outputFolder,'dir'), mkdir(outputFolder); end

mdl = 'DCLINK_800V_LOGIC';
modelFile = fullfile(outputFolder,[mdl '.slx']);
if bdIsLoaded(mdl), close_system(mdl,0); end
if exist(modelFile,'file'), delete(modelFile); end
new_system(mdl); open_system(mdl);
set_param(mdl,'SolverType','Fixed-step','Solver','FixedStepDiscrete', ...
    'FixedStep','0.001','StopTime','6','SaveOutput','on');

names = {'Wake','Shutdown','HVIL_OK','Isolation_OK','Neg_Aux','Pos_Aux', ...
    'Pre_Aux','Vpack_V','Vdc_V','Reset'};
for k=1:numel(names)
    add_block('simulink/Sources/In1',[mdl '/' names{k}], ...
        'Port',num2str(k),'Position',[35 25+45*(k-1) 65 39+45*(k-1)]);
end

logic=[mdl '/HV_Contactor_Controller'];
add_block('simulink/User-Defined Functions/MATLAB Function',logic, ...
    'Position',[235 90 515 405]);

code = fileread(fullfile(fileparts(mfilename('fullpath')),'dclink_logic_function.txt'));
rt = sfroot;
chart = rt.find('-isa','Stateflow.EMChart','Path',logic);
assert(~isempty(chart),'MATLAB Function chart was not created.');
chart.Script = code;

outs={'Neg_Cmd','Pos_Cmd','Pre_Cmd','Discharge_Cmd','Torque_Enable','State','DTC'};
for k=1:numel(outs)
    add_block('simulink/Sinks/Out1',[mdl '/' outs{k}], ...
        'Port',num2str(k),'Position',[690 85+45*(k-1) 720 99+45*(k-1)]);
end

% Force block update so MATLAB Function ports reflect the function signature.
set_param(mdl,'SimulationCommand','update');
for k=1:numel(names), add_line(mdl,[names{k} '/1'],['HV_Contactor_Controller/' num2str(k)],'autorouting','on'); end
for k=1:numel(outs), add_line(mdl,['HV_Contactor_Controller/' num2str(k)],[outs{k} '/1'],'autorouting','on'); end

% Requirement annotations.
add_block('built-in/Note',[mdl '/Sequence_Requirements'], ...
    'Position',[785 70 1120 220], ...
    'Text',['States: OFF > SELF_TEST > NEG_CLOSE > PRECHARGE > MAIN_CLOSE > RUN' newline ...
    'Precharge command threshold: Vdc/Vpack >= 0.93 to guarantee >=0.90 actual' newline ...
    'Timeouts: self-test 20 ms; contactors 50 ms; precharge 350 ms' newline ...
    'Torque enable is legal only in RUN.']);
add_block('built-in/Note',[mdl '/Local_Validation'], ...
    'Position',[785 255 1120 370], ...
    'Text',['Run Model Advisor and requirements-based tests locally.' newline ...
    'Replace boolean auxiliary feedback with debounced production signals.' newline ...
    'Record MATLAB release, checksum and test evidence.']);

save_system(mdl,modelFile);
fprintf('Created logical Simulink model: %s\n',modelFile);
end

